import json, numpy as np
R=[json.loads(l) for l in open('runs.jsonl')]
for r in R: print(r['batch'], r['tokens_B'], r['steps'], f"{r['lr']:.2e}", r['wd'], r['final_val_loss'])
def fit(pts):
    x=np.log([p[0] for p in pts]); y=np.array([p[1] for p in pts])
    a,b,c=np.polyfit(x,y,2); xo=-b/(2*a); return np.exp(xo), a, c-b*b/(4*a)
groups={}
for r in R:
    groups.setdefault((r['batch'],r['steps'],r['wd']),[]).append((r['lr'],r['final_val_loss']))
for k,v in groups.items():
    if len(v)>=3:
        lo,a,m=fit(v); print(k, f"lr*={lo:.3e} curv={a:.3f} minloss={m:.4f}")
EOF
